package com.interview.fraud;
import static org.assertj.core.api.Assertions.assertThat; import javax.sql.DataSource; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.DynamicPropertyRegistry; import org.springframework.test.context.DynamicPropertySource; import org.testcontainers.containers.PostgreSQLContainer; import org.testcontainers.junit.jupiter.Container; import org.testcontainers.junit.jupiter.Testcontainers; import org.testcontainers.utility.DockerImageName;
@Testcontainers(disabledWithoutDocker=true) @SpringBootTest class PostgresMigrationTest {@Container static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>(DockerImageName.parse("pgvector/pgvector:pg16").asCompatibleSubstituteFor("postgres"));@DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);r.add("spring.kafka.listener.auto-startup",()->"false");}@Autowired DataSource dataSource;@Test void flywayCreatesSourceOfTruthSchema()throws Exception{try(var c=dataSource.getConnection();var s=c.createStatement();var rs=s.executeQuery("SELECT COUNT(*) FROM investigation_cases")){assertThat(rs.next()).isTrue();}}}
